CREATE FUNCTION public.booking_test_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',message; END IF; RAISE NOTICE 'PASS: %',message; END $$;
CREATE FUNCTION public.booking_test_reject(statement text,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS: %',message; RETURN; END; RAISE EXCEPTION 'FAIL: expected rejection: %',message; END $$;
SELECT booking_test_assert(NOT has_table_privilege('authenticated','provider_booking_requests','INSERT,UPDATE,DELETE'),'booking direct writes revoked');
SELECT booking_test_assert(NOT has_table_privilege('authenticated','provider_booking_settings','INSERT,UPDATE,DELETE'),'schedule direct writes revoked');
SELECT booking_test_assert(NOT has_table_privilege('authenticated','provider_booking_events','INSERT,UPDATE,DELETE'),'booking history immutable');
SELECT booking_test_assert(NOT has_function_privilege('anon','request_provider_booking(uuid,integer,timestamptz,uuid,uuid,uuid,text,text,text)','EXECUTE'),'anonymous request privilege revoked');
SET LOCAL ROLE anon;
SELECT booking_test_assert((SELECT count(*)=30 FROM get_provider_booking_slots(current_setting('booking_test.service')::uuid,(current_setting('booking_test.start')::timestamptz AT TIME ZONE 'Africa/Lagos')::date)),'public slots follow declared duration and opening hours');
SELECT booking_test_assert((SELECT min(start_at)=current_setting('booking_test.start')::timestamptz FROM get_provider_booking_slots(current_setting('booking_test.service')::uuid,(current_setting('booking_test.start')::timestamptz AT TIME ZONE 'Africa/Lagos')::date)),'WAT opening maps to the correct UTC instant');
SELECT booking_test_assert((SELECT count(*)=0 FROM get_provider_booking_slots(current_setting('booking_test.service')::uuid,current_date-1)),'past dates have no slots');
SELECT booking_test_assert((SELECT count(*)=0 FROM get_provider_booking_slots(current_setting('booking_test.service')::uuid,current_date+100)),'booking horizon enforced');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b8222222-2222-4222-8222-222222222222',true);
