SELECT booking_test_reject($q$ SELECT request_provider_booking(current_setting('booking_test.service')::uuid,1,current_setting('booking_test.start')::timestamptz,gen_random_uuid(),'b9111111-1111-4111-8111-111111111111',NULL,'08012345678','','') $q$,'stale service details require customer review');
