SELECT booking_test_assert(request_provider_booking(current_setting('booking_test.service')::uuid,2,current_setting('booking_test.start')::timestamptz,current_setting('booking_test.key')::uuid,'b9111111-1111-4111-8111-111111111111',NULL,'08012345678','','Please review this request.')=current_setting('booking_test.first')::uuid,'lost-response retry is idempotent');
