SELECT booking_test_assert((SELECT base_fee=15000 AND end_at=start_at+interval '45 minutes' AND status='pending' AND provider_address IS NULL FROM provider_booking_requests WHERE id=current_setting('booking_test.first')::uuid),'server derives fee/end and withholds clinic address until confirmation');
SELECT booking_test_reject($q$ SELECT respond_provider_booking(current_setting('booking_test.first')::uuid,1,'confirmed','') $q$,'customer cannot confirm own request');
