END $$;
SELECT booking_test_assert((SELECT count(*)=5 FROM provider_booking_requests WHERE provider_id=current_setting('booking_test.org')::uuid AND customer_id=auth.uid() AND status='pending' AND start_at>now()),'pending request cap counts only open future requests');
